  label?: string,
  isRightAligned?: boolean,
): Pick<ColDef, 'headerName' | 'headerComponent' | 'headerComponentParams'> => ({
  headerName: label ? formatCompareColumnHeader(runIndex, label) : formatCompareRunIndexHeader(runIndex),
