const buildRunColumns = (
  runs: CompareRun[],
  hideHighlights: boolean | undefined,
  build: (context: RunColumnContext) => ColDef,
): ColDef[] => runs.map((run, position) => build({ run, edge: getCompareRunEdge(position), hideHighlights }));

